# File Upload
const form = new FormData();
form.append("model", "{{MODEL_ID}}");
form.append("image[]", fileInput.files[0]);
form.append("prompt", "Replace the text on the sign with OPEN");
form.append("size", "1024x1024");
form.append("quality", "high");

const response = await fetch("{{BASE_URL}}/v1/images/edits", {
  method: "POST",
  headers: { Authorization: "Bearer {{API_KEY}}" },
  body: form
});

const data = await response.json();
console.log(data.data[0].b64_json);

# Image URL
const response = await fetch("{{BASE_URL}}/v1/images/edits", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    Authorization: "Bearer {{API_KEY}}"
  },
  body: JSON.stringify({
    model: "{{MODEL_ID}}",
    image: "https://example.com/input.jpg",
    prompt: "Replace the text on the sign with OPEN",
    size: "1024x1024",
    quality: "high"
  })
});

const data = await response.json();
console.log(data.data[0].url);

templates.curl:
curl -X POST {{BASE_URL}}/dashscope/api/v1/services/aigc/image-generation/generation \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer {{API_KEY}}" \
  -H "X-DashScope-Async: enable" \
  -d '{
    "model": "{{MODEL_ID}}",
    "input": {
      "messages": [
        {
          "role": "user",
          "content": [
            {"text": "一只可爱的橘猫，数字艺术风格"}
          ]
        }
      ]
    },
    "parameters": {
      "size": "2K",
      "n": 1,
      "watermark": false
    }
  }'

# Then query the task:
curl -X GET "{{BASE_URL}}/dashscope/api/v1/tasks/TASK_ID" \
  -H "Authorization: Bearer {{API_KEY}}"

# Step 1: Submit video generation task
curl --location '{{BASE_URL}}/dashscope/api/v1/services/aigc/video-generation/video-synthesis' \
    -H 'X-DashScope-Async: enable' \
    -H 'Authorization: Bearer {{API_KEY}}' \
    -H 'Content-Type: application/json' \
    -d '{
    "model": "{{MODEL_ID}}",
    "input": {
        "prompt": "A cat running on the grass",
        "media": [
            {
                "type": "first_frame",
                "url": "https://cdn.translate.alibaba.com/r/wanx-demo-1.png"
            }
        ]
    },
    "parameters": {
        "resolution": "720P",
        "duration": 5
    }
}'

# Step 2: Query task result
curl -X GET '{{BASE_URL}}/dashscope/api/v1/tasks/{{TASK_ID}}' \
    -H 'Authorization: Bearer {{API_KEY}}'

# Step 1: Submit video generation task
curl --location '{{BASE_URL}}/dashscope/api/v1/services/aigc/video-generation/video-synthesis' \
    -H 'X-DashScope-Async: enable' \
    -H 'Authorization: Bearer {{API_KEY}}' \
    -H 'Content-Type: application/json' \
    -d '{
    "model": "{{MODEL_ID}}",
    "input": {
        "prompt": "A woman in a red cheongsam [Image 1], the camera captures her in a side medium shot outlining the fitted silhouette, then switches to a low-angle upward shot as she raises her hand to unfold a folding fan [Image 2], with tassel earrings [Image 3] swaying gently with her head movement, finally pushing into a close-up of her fingertips touching the fan ribs, showcasing oriental elegance from multiple angles.",
        "media": [
            {
                "type": "reference_image",
                "url": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20260424/mvzfud/hh-v2v-girl.jpg"
            },
            {
                "type": "reference_image",
                "url": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20260424/fvuihk/hh-v2v2-folding-fan.jpg"
            },
            {
                "type": "reference_image",
                "url": "https://help-static-aliyun-doc.aliyuncs.com/file-manage-files/zh-CN/20260424/imerii/hh-v2v-earrings.jpg"
            }
        ]
    },
    "parameters": {
        "resolution": "720P",
        "ratio": "16:9",
        "duration": 5
    }
}'

# Step 2: Query task result
curl -X GET '{{BASE_URL}}/dashscope/api/v1/tasks/{{TASK_ID}}' \
    -H 'Authorization: Bearer {{API_KEY}}'

# Step 1: Submit video generation task
curl --location '{{BASE_URL}}/dashscope/api/v1/services/aigc/video-generation/video-synthesis' \
    -H 'X-DashScope-Async: enable' \
    -H 'Authorization: Bearer {{API_KEY}}' \
    -H 'Content-Type: application/json' \
    -d '{
    "model": "{{MODEL_ID}}",
    "input": {
        "prompt": "A miniature city built from cardboard and bottle caps, coming alive at night. A tiny cardboard train rolls slowly through, its small lights twinkling and illuminating the way ahead."
    },
    "parameters": {
        "resolution": "720P",
        "ratio": "16:9",
        "duration": 5
    }
}'

# Step 2: Query task result
curl -X GET '{{BASE_URL}}/dashscope/api/v1/tasks/{{TASK_ID}}' \
    -H 'Authorization: Bearer {{API_KEY}}'
